 android.content.SharedPreferences prefs; LinearLayout root,body,nav; TextView status; LocationManager lm; Location fix; long fixAt; boolean parked=false,split=false,active=false; String primary="Inicio",secondary="Instrumentos"; int bg,card,fg,accent; float font; int ratio=50; ArrayList<TextView> live=new ArrayList<>(); ArrayList<WebView> browsers=new ArrayList<>(); Performance performance; String perfStatus="Sin prueba activa"; String pendingReport=""; final int EXPORT=401; VehicleSignals signals; CloudReader cloud=new CloudReader(); String cloudText="Sin conexión configurada"; String cloudHost=""; String cloudToken=""; String cloudEntities=""; boolean cloudBusy=false; TripMeter trip=new TripMeter(); ArrayList<TextView> signalViews=new ArrayList<>(),tripViews=new ArrayList<>(),cloudViews=new ArrayList<>();
