 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("c10",MODE_PRIVATE);lm=(LocationManager)getSystemService(LOCATION_SERVICE);split=prefs.getBoolean("split",false);ratio=prefs.getInt("ratio",50);primary=prefs.getString("primary","Inicio");secondary=prefs.getString("secondary","Instrumentos"); signals=new VehicleSignals(this);radio=new RadioAudio(this);render();}
 @Override protected void onResume(){super.onResume();active=true;signals.start();startGPS();handler.removeCallbacks(tick);handler.post(tick);}
 @Override protected void onPause(){boolean mediaVisible=tv!=null||!browsers.isEmpty();active=false;parked=false;stopTv();radio.stop();signals.stop();trip.gap();stopGPS();handler.removeCallbacks(tick);if(mediaVisible)render();super.onPause();}
 @Override protected void onDestroy(){clearBrowsers();radio.stop();handler.removeCallbacks(tick);super.onDestroy();}
 final Runnable tick=new Runnable(){public void run(){if(!active)return;if(parked&&!stationary()){parked=false;render();}refreshLive();handler.postDelayed(this,500);}};
 boolean gpsAllowed(){return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
 @android.annotation.SuppressLint("MissingPermission") void startGPS(){if(!gpsAllowed())return;try{lm.requestLocationUpdates(LocationManager.GPS_PROVIDER,500,0,this);}catch(Exception e){}}
 void stopGPS(){try{lm.removeUpdates(this);}catch(Exception e){}fix=null;fixAt=0;}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==17){startGPS();refreshLive();}}
 void askGPS(){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},17);}
 boolean fresh(){return fix!=null&&SystemClock.elapsedRealtime()-fixAt<3500&&fix.hasSpeed()&&fix.hasAccuracy()&&fix.getAccuracy()<=25;}
 boolean stationary(){return fresh()&&fix.getSpeed()<0.5f;}
 boolean videoAllowed(){return active&&parked&&stationary();}
 @Override public void onLocationChanged(Location l){fix=l;fixAt=l.getElapsedRealtimeNanos()/1000000;if(fresh()){SpeedGraph.add(speedHistory,fixAt,l.getSpeed()*3.6f);}if(fresh()&&l.getAccuracy()<=15&&(!l.hasSpeedAccuracy()||l.getSpeedAccuracyMetersPerSecond()<=1.5f))trip.sample(fixAt,l.getSpeed()*3.6);else trip.gap();if(parked&&!stationary()){parked=false;render();}if(performance!=null&&fresh()&&l.getAccuracy()<=15&&(!l.hasSpeedAccuracy()||l.getSpeedAccuracyMetersPerSecond()<=1.5f)){Double old=performance.result;performance.sample(l.getElapsedRealtimeNanos()/1000000,l.getSpeed()*3.6);perfStatus=performance.status();if(old==null&&performance.result!=null){addHistory(performance.low+"–"+performance.high+" km/h · "+perfStatus);performance=null;}}refreshLive();}
 @Override public void onProviderEnabled(String s){} @Override public void onProviderDisabled(String s){fix=null;if(parked){parked=false;render();}} @Override public void onStatusChanged(String s,int i,Bundle b){}
 void clearBrowsers(){stopTv();for(WebView w:browsers){try{w.stopLoading();w.onPause();if(w.getParent() instanceof ViewGroup)((ViewGroup)w.getParent()).removeView(w);w.destroy();}catch(Exception e){}}browsers.clear();}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;} LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
