 root=col();root.setBackgroundColor(bg);root.setPadding(dp(8),dp(4),dp(8),dp(4));setContentView(root);LinearLayout head=row();TextView brand=text("C10 COCKPIT ONE",19,accent);brand.setTypeface(null,Typeface.BOLD);head.addView(brand,new LinearLayout.LayoutParams(0,-2,1));status=text("",13,fg);head.addView(status);head.addView(button(split?"Pantalla completa":"Dividir pantalla",()->{split=!split;prefs.edit().putBoolean("split",split).apply();render();}));root.addView(head);
