 void graph(LinearLayout l,boolean gauge){SpeedGraph g=new SpeedGraph(this,card,fg,accent,gauge);graphs.add(g);l.addView(g,new LinearLayout.LayoutParams(-1,dp(210)));}
 void go(String s){primary=s;render();} void live(LinearLayout l){TextView t=text("",20,fg);live.add(t);l.addView(t);} void refreshLive(){String speed=fresh()?String.format(Locale.US,"%.1f km/h",fix.getSpeed()*3.6):"GPS sin dato válido";if(status!=null)status.setText(speed+"  ·  "+(videoAllowed()?"Vídeo autorizado manualmente":"Vídeo bloqueado"));for(TextView t:live)t.setText(speed+"\n"+perfStatus);for(TextView t:signalViews)t.setText(signals.report());for(TextView t:tripViews)t.setText(trip.summary());for(TextView t:cloudViews)t.setText(cloudText);for(TextView t:radioViews)t.setText(radio.status());for(TextView t:dashboardViews)t.setText(radio.status()+"  ·  "+(fresh()?"GPS válido":"GPS sin señal"));for(SpeedGraph g:graphs)g.update(speedHistory,fresh()?fix.getSpeed()*3.6f:null,SystemClock.elapsedRealtime());}
 void arm(int lo,int hi){if(!gpsAllowed()){askGPS();return;}new AlertDialog.Builder(this).setMessage("¿Prueba en recinto cerrado y seguro?").setPositiveButton("Preparar",(d,w)->{performance=new Performance(lo,hi);perfStatus="Esperando inicio "+lo+"–"+hi;refreshLive();}).setNegativeButton("Cancelar",null).show();}
 void parkedPrompt(){if(!gpsAllowed()){askGPS();return;}if(!stationary()){toast("Necesitas una señal GPS reciente y velocidad prácticamente cero. El GPS no confirma la posición P.");return;}new AlertDialog.Builder(this).setTitle("Solo estacionado").setMessage("Confirma que el vehículo está estacionado en P y con freno de estacionamiento. El GPS no puede comprobar el freno ni la posición P.").setPositiveButton("Estoy estacionado",(d,w)->{parked=stationary();render();}).setNegativeButton("Cancelar",null).show();}
 void radioPanel(LinearLayout l){label(l,"Solo audio · no requiere GPS ni confirmar estacionamiento. Elige emisora antes de iniciar la marcha o mediante el acompañante.");TextView t=text(radio.status(),20,fg);radioViews.add(t);l.addView(t);for(int i=0;i<RadioAudio.NAMES.length;i++){final int n=i;btn(l,RadioAudio.NAMES[i],()->{if(!active)return;if(tv!=null){toast("Cierra el panel de TV antes de reproducir radio");return;}radio.play(n);refreshLive();});}btn(l,"Detener radio",()->{radio.stop();refreshLive();});label(l,"La radio continúa al cambiar de pestaña dentro de esta app. Se detiene al salir, al perder el foco de audio o al fallar la conexión. Emisiones por Internet, pendientes de prueba en LeapOS.");}
